// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;

    function setUp() public {
        c = new LRTDepositPool();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Initialization may be blocked (constructor disabled initializers); wrap in try/catch so
        // this never reverts. Either way, no pause()/unpause() path was ever successfully executed.
        vm.prank(actor);
        try c.initialize(actor) {
            // initialized
        } catch {
            // constructor disabled initializers; contract still fresh, _paused == false
        }
        // Rule: paused() reflects the real pause state, which is false because nothing paused it.
        assertTrue(c.paused() == false, "paused() must report actual state, initially false");
    }
}
